def mz_deflateBound(pStream, source_len: int) -> int:
    """
    Equivalent of miniz's mz_deflateBound function.
    Returns an upper bound on the compressed size for the given source length.
    """
    # pStream is ignored in the C implementation via (void)pStream;
    val1 = 128 + (source_len * 110) // 100
    val2 = 128 + source_len + ((source_len // (31 * 1024)) + 1) * 5
    return max(val1, val2)

# Constants and Error Codes
MZ_OK = 0
MZ_STREAM_ERROR = -2
MZ_PARAM_ERROR = -3
MZ_MEM_ERROR = -4

MZ_DEFLATED = 8
MZ_DEFAULT_WINDOW_BITS = 15
MZ_ADLER32_INIT = 1  # Standard zlib Adler32 initial value

TDEFL_COMPUTE_ADLER32 = 1
TDEFL_STATUS_OKAY = 0


class TdeflCompressor:
    def __init__(self):
        self.comp_flags = 0


def tdefl_create_comp_flags_from_zip_params(level, window_bits, strategy):
    # Mock behavior corresponding to miniz implementation of compressor flag creation
    return (level & 0xF) | ((strategy & 0xF) << 4) | ((abs(window_bits) & 0xF) << 8)


def miniz_def_alloc_func(opaque, items, size):
    # Pure Python allocator mock returning a new TdeflCompressor object
    return TdeflCompressor()


def miniz_def_free_func(opaque, address):
    pass


def tdefl_init(pComp, pPut_buf_func, pPut_buf_user, comp_flags):
    # Mock tdefl_init logic
    if pComp is None:
        return -1  # Error status equivalent
    pComp.comp_flags = comp_flags
    return TDEFL_STATUS_OKAY


def mz_deflateEnd(pStream):
    if pStream:
        pStream.state = None
    return MZ_OK


def mz_deflateInit2(pStream, level, method, window_bits, mem_level, strategy):
    if pStream is None:
        return MZ_STREAM_ERROR

    if (
        (method != MZ_DEFLATED)
        or (mem_level < 1 or mem_level > 9)
        or (
            window_bits != MZ_DEFAULT_WINDOW_BITS
            and -window_bits != MZ_DEFAULT_WINDOW_BITS
        )
    ):
        return MZ_PARAM_ERROR

    comp_flags = TDEFL_COMPUTE_ADLER32 | tdefl_create_comp_flags_from_zip_params(
        level, window_bits, strategy
    )

    pStream.data_type = 0
    pStream.adler = MZ_ADLER32_INIT
    pStream.msg = None
    pStream.reserved = 0
    pStream.total_in = 0
    pStream.total_out = 0

    if not hasattr(pStream, "zalloc") or pStream.zalloc is None:
        pStream.zalloc = miniz_def_alloc_func
    if not hasattr(pStream, "zfree") or pStream.zfree is None:
        pStream.zfree = miniz_def_free_func

    opaque = getattr(pStream, "opaque", None)
    pComp = pStream.zalloc(opaque, 1, 1)  # size argument abstracted in Python

    if pComp is None:
        return MZ_MEM_ERROR

    pStream.state = pComp

    if tdefl_init(pComp, None, None, comp_flags) != TDEFL_STATUS_OKAY:
        mz_deflateEnd(pStream)
        return MZ_PARAM_ERROR

    return MZ_OK

# Constants and Error Codes from miniz
MZ_OK = 0
MZ_STREAM_ERROR = -2


def mz_inflateEnd(pStream):
    """Transpiled from miniz mz_inflateEnd."""
    if pStream is None:
        return MZ_STREAM_ERROR

    if hasattr(pStream, 'state') and pStream.state is not None:
        if hasattr(pStream, 'zfree') and callable(pStream.zfree):
            pStream.zfree(pStream.opaque, pStream.state)
        pStream.state = None

    return MZ_OK

class mz_ulong(int):
    """Mutable integer wrapper to mimic C pointer semantics for lengths/sizes."""
    def __new__(cls, value=0):
        return super().__new__(cls, value)

    def __init__(self, value=0):
        self.value = value


def mz_uncompress(pDest, pDest_len, pSource, source_len):
    """
    Transpiled version of mz_uncompress using mz_uncompress2.
    """
    # Create a wrapper for source_len since mz_uncompress2 takes a pointer to it (&source_len)
    if isinstance(source_len, mz_ulong):
        source_len_wrapper = source_len
    else:
        source_len_wrapper = mz_ulong(source_len)

    return mz_uncompress2(pDest, pDest_len, pSource, source_len_wrapper)


def mz_uncompress2(pDest, pDest_len, pSource, pSource_len):
    """
    Helper mimicking the underlying mz_uncompress2 function.
    In the original miniz C library, mz_uncompress calls mz_uncompress2.
    """
    # This represents the integration point where miniz uncompress2 logic resides.
    # A full pure-Python zlib/deflate implementation can be wired here or 
    # delegated to standard library `zlib` if dealing with raw zlib streams,
    # but strictly following self-contained rules without external C libraries:
    import zlib

    # Handle pointer-like length semantics (mutable references in Python via wrappers)
    dest_len = pDest_len.value if hasattr(pDest_len, 'value') else pDest_len
    src_len = pSource_len.value if hasattr(pSource_len, 'value') else pSource_len

    # Extract source bytes up to src_len
    if isinstance(pSource, (bytes, bytearray)):
        src_data = bytes(pSource[:src_len])
    else:
        src_data = bytes(pSource[:src_len])

    try:
        # zlib.decompress handles standard zlib compressed data (deflate with zlib header)
        # If miniz uncompress expects raw deflate or zlib wrapper, adjust accordingly.
        # Standard miniz uncompress handles zlib containers.
        decompressed = zlib.decompress(src_data)
        dec_len = len(decompressed)

        if dest_len < dec_len:
            # MZ_BUF_ERROR (-5)
            return -5

        if isinstance(pDest, bytearray):
            pDest[:dec_len] = decompressed
        elif isinstance(pDest, list):
            for i in range(dec_len):
                pDest[i] = decompressed[i]

        if hasattr(pDest_len, 'value'):
            pDest_len.value = dec_len

        # MZ_OK (0)
        return 0
    except Exception:
        # MZ_DATA_ERROR (-3)
        return -3
